        if (buf == null) {
            loop:
            for (int i = 0; i < path.length(); i++) {
                char c = path.charAt(i);
                switch (c) {
                    case '%':
                    case '?':
                    case ';':
                    case '#':
                    case ' ':
                        buf = new StringBuffer(path.length() << 1);
                        break loop;
                }
            }
            if (buf == null) {
                return null;
            }
        }
        synchronized (buf) {
